"""Module holding the implementation for providing BIP log specific log file.
"""
import os
import logging
logger = logging.getLogger()


class CloudGnbBipLogFileProvider:
    """Class to get the trace file for bip logs. Only the format of pcap is supported for bip trace files.
    """

    def get_bip_log_file(self, log_directory, collector_config):
        """Determines the pcap location of the collected bip trace and return it

        :param str log_directory: the path where the log files of the collector are stored
        :param str collector_config: the collector configuration of the collector to obtain additional information
        """
        # we need to add pdump collector
        bip_traces = []
        for sub_collector in collector_config['members']:

            sub_log_directory = os.path.join(log_directory, sub_collector)
            logger.warning(f"Sub log directory is {sub_log_directory}")
            pcap_files = [filename for filename in os.listdir(sub_log_directory)
                          if filename.lower().endswith(".pcap")]
            bip_traces += [os.path.join(sub_log_directory, filename) for filename in pcap_files]
        return bip_traces
